"use client";
import { ArtemisScope } from "./artemis-scope";
import View3 from "./components/step-form/variants/04-onboarding";
function CompactOnboarding(){return <View3 compact/>;}
const variants={"onboarding-compact":CompactOnboarding};
export interface ArtemisStepFormProps { className?: string; variant?: "onboarding-compact"; }
export function ArtemisStepForm({className,variant="onboarding-compact"}:ArtemisStepFormProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState, type FormEvent } from "react";
import { ArrowLeft, ArrowRight, Check, RotateCcw } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { Field, type FieldKey, type FieldSpec } from "./04-onboarding/fields";
import { Progress } from "./04-onboarding/progress";
type Step = {
    label: string;
    title: string;
    description: string;
    fields: readonly FieldSpec[];
};
const STEPS: readonly Step[] = [
    { label: "Profile", title: "Tell us about you", description: "Start with the basics. You can change these details later.", fields: [{ key: "firstName", label: "First name", kind: "text", placeholder: "Alex", autoComplete: "given-name", required: true, span: 6 }, { key: "lastName", label: "Last name", kind: "text", placeholder: "Reed", autoComplete: "family-name", required: true, span: 6 }, { key: "email", label: "Work email", kind: "email", placeholder: "alex.reed@example.com", autoComplete: "email", required: true, span: 12 }] },
    { label: "Workspace", title: "Set up your workspace", description: "A few details help us prepare the right starting point.", fields: [{ key: "company", label: "Company or team", kind: "text", placeholder: "Workspace Studio", autoComplete: "organization", required: true, span: 12 }, { key: "role", label: "Your role", kind: "select", placeholder: "Select a role", options: ["Founder", "Design", "Engineering", "Product"], required: true, span: 6 }, { key: "teamSize", label: "Team size", kind: "select", placeholder: "Select a size", options: ["Just me", "2\u201310 people", "11\u201350 people", "51+ people"], required: true, span: 6 }] },
    { label: "Goals", title: "What should we optimize for?", description: "Give the workspace a little context before you arrive.", fields: [{ key: "website", label: "Company website", kind: "text", placeholder: "company.com", autoComplete: "url", span: 12 }, { key: "goal", label: "Primary goal", kind: "select", placeholder: "Choose your main goal", options: ["Launch something new", "Improve an existing product", "Explore and prototype"], required: true, span: 12 }, { key: "context", label: "Anything else we should know?", kind: "textarea", placeholder: "A short note about what you are building", span: 12 }] },
];
const EMPTY: Record<FieldKey, string> = { firstName: "", lastName: "", email: "", company: "", role: "", teamSize: "", website: "", goal: "", context: "" };
const COMMON = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50";
const GHOST = `${COMMON} art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-1.5 art:px-3 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background`;
const PRIMARY = `${COMMON} art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full`;
export default function StepFormOnboarding({ compact = false }: { compact?: boolean } = {}) {
    const reduce = useReducedMotion();
    const id = useId();
    const root = useRef<HTMLDivElement>(null);
    const [step, setStep] = useState(0);
    const [direction, setDirection] = useState(1);
    const [values, setValues] = useState(EMPTY);
    const [errors, setErrors] = useState<Partial<Record<FieldKey, string>>>({});
    const done = step === STEPS.length;
    const current = STEPS[Math.min(step, 2)]!;
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    function change(key: FieldKey, value: string) { setValues(previous => ({ ...previous, [key]: value })); setErrors(previous => ({ ...previous, [key]: "" })); }
    function submit(event: FormEvent) {
        event.preventDefault();
        if (done)
            return;
        const next: Partial<Record<FieldKey, string>> = {};
        for (const field of current.fields) {
            const value = values[field.key].trim();
            if (field.required && !value)
                next[field.key] = "This is required.";
            else if (field.kind === "email" && value && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))
                next[field.key] = "Enter a valid email address.";
        }
        setErrors(next);
        const first = current.fields.find(field => next[field.key]);
        if (first) {
            root.current?.querySelector(`[data-onboarding-field="${first.key}"]`)?.querySelector<HTMLElement>("input,textarea,button[aria-haspopup]")?.focus({ preventScroll: true });
            return;
        }
        setDirection(1);
        setStep(previous => previous + 1);
    }
    function back() { setErrors({}); setDirection(-1); setStep(previous => Math.max(0, previous - 1)); }
    function reset() { setValues(EMPTY); setErrors({}); setDirection(-1); setStep(0); }
    return <div className="art:flex art:w-full art:flex-col art:items-center art:justify-center">

    <section className="art:w-full"><motion.div ref={root} layout={reduce ? false : "size"} className="art:mx-auto art:w-full art:max-w-3xl art:rounded-2xl art:border art:border-border/55 art:bg-background" transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}>
      <div className="art:shrink-0 art:border-border/45 art:border-b art:px-5 art:py-5 art:@min-[640px]/artemis:px-8"><div className="art:flex art:items-center art:justify-between art:gap-6"><div><p className="art:font-medium art:text-foreground art:text-sm art:tracking-tight">Set up your account</p><p className="art:mt-0.5 art:text-muted-foreground art:text-xs">Usually takes less than two minutes</p></div>{!done && <span className="art:shrink-0 art:rounded-full art:border art:border-border/60 art:px-2.5 art:py-1 art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">{step + 1}{" / "}{STEPS.length}</span>}</div>{!done && <Progress step={step} compact={compact}/>}</div>
      <form noValidate onSubmit={submit} className="art:overflow-x-clip art:overflow-y-visible"><AnimatePresence mode="wait" initial={false}><motion.div key={step} tabIndex={done ? undefined : -1} aria-labelledby={done ? undefined : `${id}-title`} className={done ? "art:px-6 art:py-16 art:text-center art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-20" : "art:px-5 art:pt-7 art:pb-6 art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:pt-9 art:@min-[640px]/artemis:pb-8 art:outline-none"} initial={reduce ? false : { opacity: 0, transform: `translateX(${direction * 18}px)` }} animate={{ opacity: 1, transform: "translateX(0px)" }} exit={{ opacity: 0, transform: `translateX(${-direction * 14}px)` }} transition={reduce ? { duration: 0 } : { duration: 0.22, ease: ARTEMIS_EASE_OUT }}>
        {done ? <><motion.span className="art:mx-auto art:grid art:size-11 art:place-items-center art:rounded-full art:bg-foreground art:text-background" initial={reduce ? false : { opacity: 0, scale: 0.86 }} animate={{ opacity: 1, scale: 1 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT}><Check className="art:size-5"/></motion.span><h2 className="art:mt-5 art:text-foreground art:tracking-tight art:text-xl art:font-medium">Your workspace is ready.</h2><p className="art:mx-auto art:mt-2 art:max-w-sm art:text-muted-foreground art:text-sm art:leading-6">Everything is set up. You can start inviting your team.</p><motion.button type="button" className={`${GHOST} art:mt-5 art:h-9 art:rounded-full`} tabIndex={0} onClick={reset} {...press}><RotateCcw className="art:size-3.5"/>Start again</motion.button></> : <><p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.14em]">{current.label}</p><div className="art:mt-2 art:flex art:items-center art:justify-between art:gap-3"><h2 id={`${id}-title`} className="art:text-foreground art:tracking-tight art:text-xl art:font-medium">{current.title}</h2></div><p className="art:mt-2 art:max-w-lg art:text-muted-foreground art:text-sm art:leading-6">{current.description}</p><div data-onboarding-body="true" className="art:mt-7 art:grid art:grid-cols-12 art:gap-x-4 art:gap-y-5">{current.fields.map(field => <Field key={field.key} spec={field} baseId={id} value={values[field.key]} error={errors[field.key] ?? ""} onChange={value => change(field.key, value)}/>)}</div><div className="art:mt-2 art:flex art:items-center art:justify-between"><motion.button type="button" className={`${GHOST} art:-ml-3 art:h-9 art:rounded-full`} disabled={step === 0} tabIndex={0} onClick={back} {...press}><ArrowLeft className="art:size-3.5"/>Back</motion.button><motion.button type="submit" className={PRIMARY} tabIndex={0} {...press}>{step === 2 ? "Create workspace" : "Continue"}<ArrowRight className="art:size-4"/></motion.button></div></>}
      </motion.div></AnimatePresence></form>
    </motion.div></section>
  </div>;
}

"use client";
// @zeus-internal
import type { CSSProperties } from "react";
import { ArtemisValidationFrame } from "../../../../lib/validation-frame";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "./select";
export type FieldKey = "firstName"|"lastName"|"email"|"company"|"role"|"teamSize"|"website"|"goal"|"context";
export type FieldSpec = { key:FieldKey;label:string;required?:boolean;span:6|12 } & ({kind:"text"|"email";placeholder:string;autoComplete:string}|{kind:"select";placeholder:string;options:readonly string[]}|{kind:"textarea";placeholder:string});
export function Field({spec,baseId,value,error,onChange}:{spec:FieldSpec;baseId:string;value:string;error:string;onChange:(value:string)=>void}) {
 const id=`${baseId}-${spec.key}`,description=error?`${id}-error`:undefined;
 const label=<>{spec.label}{spec.required&&<span aria-hidden="true" className="art:ml-1 art:text-muted-foreground">*</span>}</>;
 return <div data-onboarding-field={spec.key} className={`art:min-w-0 art:[grid-column:span_var(--field-span)] ${spec.span===6?"art:@max-[640px]/artemis:col-span-12":""}`} style={{"--field-span":spec.span} as CSSProperties}>
  {spec.kind==="select"?<fieldset className="art:min-w-0" aria-labelledby={`${id}-label`} aria-invalid={!!error} aria-describedby={description}><Select value={value} onValueChange={onChange}><label><span id={`${id}-label`} className="art:mb-2 art:block art:text-xs art:font-medium art:text-foreground">{label}</span><SelectTrigger aria-label={spec.label} className="art:h-11 art:border-0 art:bg-muted/55 art:py-0 art:focus:bg-muted art:focus-visible:ring-foreground/10"><SelectValue placeholder={spec.placeholder}/></SelectTrigger></label><SelectContent className="art:border-border/55">{spec.options.map(option=><SelectItem key={option} value={option}>{option}</SelectItem>)}</SelectContent></Select></fieldset>:<><label htmlFor={id} className="art:mb-2 art:block art:text-xs art:font-medium art:text-foreground">{label}</label>{spec.kind==="textarea"?<textarea id={id} name={spec.key} value={value} onChange={event=>onChange(event.target.value)} placeholder={spec.placeholder} aria-invalid={!!error} aria-describedby={description} className="art:min-h-24 art:w-full art:resize-none art:rounded-xl art:border-0 art:bg-muted/55 art:px-3.5 art:py-3 art:text-sm art:text-foreground art:outline-none art:transition-colors art:placeholder:text-muted-foreground/60 art:focus:bg-muted art:focus-visible:ring-2 art:focus-visible:ring-foreground/10"/>:<ArtemisValidationFrame error={!!error}><input id={id} name={spec.key} type={spec.kind} value={value} onChange={event=>onChange(event.target.value)} placeholder={spec.placeholder} required={spec.required} autoComplete={spec.autoComplete} aria-invalid={!!error} aria-describedby={description} className="art:h-full art:w-full art:bg-transparent art:px-3.5 art:text-sm art:leading-6 art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60"/></ArtemisValidationFrame>}</>}
  <p id={`${id}-error`} aria-live="polite" className="art:min-h-5 art:pt-1 art:text-xs art:text-destructive">{error}</p>
 </div>;
}

"use client";
// @zeus-internal
import { Check } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
