    const reduce = useReducedMotion();
    const transition = reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT;
    return <ol aria-label="Progress" data-progress-style={compact ? "compact" : "steps"} className={compact ? "art:mt-6 art:grid art:gap-2" : "art:mt-6 art:grid art:gap-3 art:overflow-x-auto art:pb-1"} style={{ gridTemplateColumns: compact ? "repeat(3, minmax(0px, 1fr))" : "repeat(3, minmax(5rem, 1fr))" }}>{LABELS.map((label, index) => <li key={label} className="art:min-w-0" aria-current={index === step ? "step" : undefined} aria-label={label}>
    {compact ? <><span className="art:sr-only">{label}</span><span aria-hidden="true" className="art:relative art:block art:h-1.5 art:overflow-hidden art:rounded-full art:bg-muted"><motion.span className="art:absolute art:inset-0 art:origin-left art:rounded-full art:bg-foreground" initial={false} animate={{ opacity: index < step ? 0.6 : 1, scaleX: index <= step ? 1 : 0 }} transition={transition}/></span></> : <div className="art:flex art:flex-col art:items-start art:gap-2 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center art:@min-[640px]/artemis:gap-2.5"><span className={`art:grid art:size-7 art:shrink-0 art:place-items-center art:rounded-full art:border art:font-medium art:text-xs art:transition-colors ${index === step ? "art:border-foreground art:bg-foreground art:text-background" : index < step ? "art:border-border art:bg-muted art:text-foreground" : "art:border-border/70 art:text-muted-foreground"}`}>{index < step ? <Check className="art:size-3"/> : index + 1}</span><span className={`art:truncate art:text-xs art:transition-colors ${index === step ? "art:font-medium art:text-foreground" : "art:text-muted-foreground"}`}>{label}</span>{index < 2 && <div aria-hidden="true" className="art:relative art:ml-1 art:hidden art:h-px art:min-w-2 art:flex-1 art:overflow-hidden art:bg-border/60 art:@min-[640px]/artemis:block"><motion.div className="art:absolute art:inset-0 art:origin-left art:bg-foreground/40" initial={false} animate={{ scaleX: index < step ? 1 : 0 }} transition={transition}/></div>}</div>}
  </li>)}</ol>;
}

"use client";
// @zeus-internal
import { Check, ChevronDown } from "lucide-react";
import { motion, useReducedMotion, type Transition } from "motion/react";
import { Children, createContext, isValidElement, useContext, useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode, type RefObject } from "react";
import { ARTEMIS_EASE_OUT } from "./ease";
