type Choice={value:string;label:ReactNode;disabled?:boolean};
interface ChoiceContext { value?:string;disabled:boolean;choices:Choice[];open:boolean;setOpen:(open:boolean)=>void;active:number;focus:(index:number)=>void;choose:(value:string)=>void;trigger:RefObject<HTMLButtonElement|null>;panel:RefObject<HTMLDivElement|null>;id:string;above:boolean;setAbove:(above:boolean)=>void; }
