export function ArtemisCompoundSelect({value,onValueChange,disabled,children}:ArtemisCompoundSelectProps){
 const root=useRef<HTMLDivElement>(null),trigger=useRef<HTMLButtonElement>(null),panel=useRef<HTMLDivElement>(null),id=useId();
 const [open,setOpen]=useState(false),[active,setActive]=useState(0),[above,setAbove]=useState(false);const search=useRef({text:"",time:0});
 const choices:Choice[]=[];const visit=(nodes:ReactNode)=>Children.forEach(nodes,node=>{if(!isValidElement<{value?:string;children?:ReactNode;disabled?:boolean}>(node))return;if(node.type===ArtemisCompoundSelectItem&&node.props.value)choices.push({value:node.props.value,label:node.props.children,disabled:node.props.disabled});else visit(node.props.children);});visit(children);
 const focus=(index:number)=>{if(index<0||choices[index]?.disabled)return;setActive(index);queueMicrotask(()=>root.current?.querySelector<HTMLButtonElement>(`[data-artemis-option="${index}"]`)?.focus());};
