  if(next>=0){event.preventDefault();focus(next);}
 };
 return <Context.Provider value={{value,disabled:!!disabled,choices,open,setOpen:next=>{if(!disabled)setOpen(next);},active,focus,choose,trigger,panel,id,above,setAbove}}><div ref={root} className="art:relative" onKeyDown={keydown} onBlur={event=>{if(event.relatedTarget instanceof Node&&!event.currentTarget.contains(event.relatedTarget))setOpen(false);}} data-disabled={disabled||undefined}>{children}</div></Context.Provider>;
}
export interface ArtemisCompoundSelectTriggerProps {children:ReactNode;className?:string;id?:string;"aria-label"?:string;}
export function ArtemisCompoundSelectTrigger({children,className,id:given,...props}:ArtemisCompoundSelectTriggerProps){
