 const corners:Record<string,number|number[]>={borderTopLeftRadius:12,borderTopRightRadius:12,borderBottomLeftRadius:12,borderBottomRightRadius:12};for(const name of near)corners[name]=reduce?12:c.open?[0,0,12]:[12,0,12];
 const transition:Record<string,Transition>=Object.fromEntries(near.map(name=>[name,reduce?{duration:0}:{duration:c.open?0.6:0.42,times:c.open?[0,0.4,1]:[0,0.5,1],ease:ARTEMIS_EASE_OUT}]));
 const reveal=(keyboard=false,last=false)=>{c.setOpen(true);if(keyboard){let index=c.choices.findIndex(item=>item.value===c.value&&!item.disabled);if(index<0){const enabled=c.choices.flatMap((item,index)=>item.disabled?[]:[index]);index=(last?enabled.at(-1):enabled[0])??-1;}c.focus(index);}};
 return <motion.button {...props} id={given??`${c.id}-trigger`} ref={c.trigger} type="button" disabled={c.disabled} aria-haspopup="listbox" aria-expanded={c.open} aria-controls={`${c.id}-options`} initial={false} animate={corners} transition={transition} className={artemisCx("art:relative art:z-10 art:flex art:h-10 art:w-full art:items-center art:justify-between art:gap-2 art:border art:border-border art:bg-background art:px-3.5 art:text-sm art:text-foreground art:outline-none art:hover:border-foreground/25 art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:pointer-events-none art:disabled:opacity-50",className)} onClick={event=>{if(c.open)c.setOpen(false);else reveal(event.detail===0);}} onKeyDown={event=>{if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();reveal(true,event.key==="ArrowUp");}}}>{children}<motion.span aria-hidden="true" className="art:text-muted-foreground" animate={{rotate:c.open?180:0}} transition={{type:"spring",duration:reduce?0:0.4,bounce:0.3}}><ChevronDown size={16}/></motion.span></motion.button>;
