export function ArtemisCompoundSelectValue({placeholder}:{placeholder?:string}){const c=useChoice();const label=c.choices.find(item=>item.value===c.value)?.label;return <span className={artemisCx("art:min-w-0 art:truncate",label?"art:text-foreground":"art:text-muted-foreground")}>{label??placeholder??"Select"}</span>;}
export function ArtemisCompoundSelectContent({children,className}:{children:ReactNode;className?:string}){
