 useLayoutEffect(()=>{const element=inner.current;if(!element)return;const measure=()=>setHeight(element.offsetHeight);measure();const observer=new ResizeObserver(measure);observer.observe(element);return()=>observer.disconnect();},[]);
 useLayoutEffect(()=>{if(!c.open||!c.trigger.current)return;const rect=c.trigger.current.getBoundingClientRect(),below=innerHeight-rect.bottom;c.setAbove(below<height+16&&rect.top>below);},[c.open,c.trigger,c.setAbove,height]);
 const radius=c.open?12:0;const shape={borderTopLeftRadius:c.above?12:radius,borderTopRightRadius:c.above?12:radius,borderBottomLeftRadius:c.above?radius:12,borderBottomRightRadius:c.above?radius:12};
